namespace ghidra.program.database.references;



using ghidra.program.database;
using ghidra.program.database.map;
using ghidra.program.model.address;
using ghidra.program.model.symbol;
using ghidra.util;
using ghidra.util;

abstract class RefList : DbObject {

	static volatile int BIG_REFLIST_THRESHOLD = 1700;

	protected static DataConverter converter = BigEndianDataConverter.INSTANCE;

	protected Address address;
	protected RecordAdapter adapter;
	protected AddressMap addrMap;
	protected ProgramDB program;
	protected bool isFrom;

	protected RefList(long key, Address address, RecordAdapter adapter, AddressMap addrMap,
			ProgramDB program, bool isFrom) : base(key)
    {
		this.address = addrMap.decodeAddress(key);
		this.adapter = adapter;
		this.addrMap = addrMap;
		this.program = program;
		this.isFrom = isFrom;
	}

	abstract void addRef(Address fromAddr, Address toAddr, RefType type, int opIndex, long symbolID,
			bool isPrimary, SourceType sourceType, bool isOffset, bool isShift,
			long offsetOrShift);

	abstract void updateRefType(Address addr, int opIndex, RefType refType);

	abstract ReferenceDB getRef(Address address, int opIndex);

	abstract bool removeRef(Address addr, int opIndex);

	abstract bool isEmpty();

	abstract bool setPrimary(Reference @ref, bool b);

	abstract ReferenceIterator getRefs();

	abstract Reference[] getAllRefs();

	abstract int getNumRefs();

	abstract Reference getPrimaryRef(int opIndex);

	abstract void removeAll();

	abstract bool setSymbolID(Reference @ref, long symbolID);

	/**
	 * Returns true if the specified opIndex has a corresponding reference.
	 * NOTE: This is only of value for the From Refs
	 * @param opIndex
	 */
	abstract bool hasReference(int opIndex);

	abstract byte getReferenceLevel();

	/**
	 * Check to see if RefList should be transitioned to a BigRefList.
	 * A replacement RefList will be returned and the corresponding adapter record
	 * updated if a transition is performed, otherwise the original
	 * RefList is returned.
	 * @param cache RefList object cache
	 * @param newSpaceRequired number of references to be added.
	 * @return original or replacement RefList
	 * @throws IOException
	 */
	public RefList checkRefListSize(DbCache<RefList> cache, int newSpaceRequired)
    {
		if (adapter != null && (getNumRefs() + newSpaceRequired) >= BIG_REFLIST_THRESHOLD) {
			cache.delete(getKey()); // remove smaller list from cache
			BigRefListV0 refList =
				BigRefListV0.createNew(address, adapter, addrMap, program, isFrom);
			cache.add(refList);
			refList.addRefs(getRefs());
			return refList;
		}
		return this;
	}

}
